P<-normalizePath('ccRCC_signature_transportability_benchmark_2026');O<-file.path(P,'84_JCO_PO_Upgrade_20261113/05_analysis/B1_operator_panel_trials');d<-read.csv(file.path(O,'results/pairwise_metrics.csv'));d<-subset(d,grepl('^Angio',signature)&operator1=='O1'&operator2%in%c('O2','O5'));d<-d[order(d$trial,d$signature,d$operator2),];y<-rev(seq_len(nrow(d)));labs<-paste(d$trial,d$signature,paste0('O1/',d$operator2));col<-ifelse(d$operator2=='O2','#24619c','#b35b28');ragg::agg_png(file.path(O,'results/diagnostic_headline_contrasts.png'),width=1800,height=1050,res=180);par(mar=c(4.7,12.5,3.5,5),family='Arial',las=1,mgp=c(2.8,.7,0));plot(d$disagreement_pct,y,xlim=c(0,max(d$ci_high)*1.25),ylim=c(.5,nrow(d)+.5),yaxt='n',xlab='Research high/low disagreement (%)',ylab='',pch=19,col=col,cex=1.1,main='B1-primary: prespecified operator contrasts');axis(2,at=y,labels=labs,tick=FALSE,cex.axis=.85);abline(v=seq(0,50,5),col='gray92',lwd=.8);segments(d$ci_low,y,d$ci_high,y,col=col,lwd=2);points(d$disagreement_pct,y,pch=19,col=col,cex=1.1);text(d$ci_high+max(d$ci_high)*.035,y,sprintf('%.2f%%',d$disagreement_pct),adj=0,cex=.8);mtext('Post hoc exploratory upgrade; 95% fixed-score patient-bootstrap CI',side=3,line=.5,cex=.8);dev.off()
